        trap: `- ❌ ~~przeciwko wojny~~ → ✅ **przeciwko wojnie** — **przeciw(ko)** + Д. (укр. *проти* + Р.).
- ❌ ~~Rozmawialiśmy po telefonie~~ → ✅ **Rozmawialiśmy przez telefon** — засіб зв’язку = **przez** + З.
- ❌ ~~Wrócę przez godzinę~~ (у значенні «через годину») → ✅ **Wrócę za godzinę** — **przez godzinę** = «протягом години».
- ❌ ~~Proszę o pomocy~~ / ~~Proszę pomocy~~ → ✅ **Proszę o pomoc** — **prosić o** + З.
- ❌ ~~Zapytał drogę~~ → ✅ **Zapytał o drogę** — «питати щось / про щось» = **pytać o** + З.
- ❌ ~~lekarstwo od kaszlu~~ → ✅ **lekarstwo na kaszel** — засіб проти чогось = **na** + З.
- ❌ ~~Ona jest na dwa lata starsza~~ → ✅ **Ona jest o dwa lata starsza** — різниця = **o** + З.
- ❌ ~~walczyć za podwyżkę~~ → ✅ **walczyć o podwyżkę** — «боротися за (здобуття чогось)» = **walczyć o** + З.; **walczyć za** + З. — лише «в ім’я, на захист»: **walczyć za ojczyznę**.
- ❌ ~~Jedziemy na morze~~ → ✅ **Jedziemy nad morze** — до моря, озера, річки як місця відпочинку = **nad** + З. (**na morze** — у відкрите море, на корабель).
- ❌ ~~Uważam go przyjacielem~~ → ✅ **Uważam go za przyjaciela** — **uważać za** + З. (✅ як укр. *вважати за друга*); орудного без **za**, як в укр. *вважати другом*, польська не допускає.
- ❌ ~~napisany Mickiewiczem~~ → ✅ **napisany przez Mickiewicza** — діяч у пасиві = **przez** + З.
- ⚠️ **skręcić w prawo / w lewo** — найнейтральніший спосіб сказати «повернути праворуч / ліворуч»; **na prawo** передусім означає «де?»: **Sklep jest na prawo** (у розмовній мові **na prawo** трапляється й про напрямок).`,
