        trap: `- ❌ ~~Mówimy o film~~ → ✅ **Mówimy o filmie** — «про» = **o** + місцевий, а не знахідний.
- ❌ ~~Jestem na pracy~~ → ✅ **Jestem w pracy** — «на роботі» = **w pracy**.
- ❌ ~~Studiuję w uniwersytecie~~ → ✅ **Studiuję na uniwersytecie** — вищі навчальні заклади (як установи) — з **na**.
- ❌ ~~Mieszkam w wsi~~ / ~~we wsi~~ (у значенні «на селі») → ✅ **Mieszkam na wsi** — «жити в селі» загалом = **na wsi**; **we wsi** — «у (конкретному) селі»: **we wsi Zalesie**.
- ⚠️ **Siedzimy za stołem** (неприродно в значенні «за їжею»; **za stołem** — про святковий / президійний стіл, **za biurkiem**, або «позаду столу») → нейтрально ✅ **Siedzimy przy stole** — «за столом» (сидіти, їсти, розмовляти) = **przy stole**.
- ❌ ~~Byliśmy na morzu~~ (про відпочинок) → ✅ **Byliśmy nad morzem** — на узбережжі = **nad**; **na morzu** — у відкритому морі, на кораблі.
- ❌ ~~Po obiadu~~ / ~~Po obiad~~ (у значенні «після») → ✅ **Po obiedzie** — «після» = **po** + Ms.
- ❌ ~~Mieszkam za adresem…~~ → ✅ **Mieszkam pod adresem…** — офіційні звороти з **pod**: адреса, номер, умова.
- ❌ ~~Między innymi, gdzie mieszkasz?~~ (у значенні «до речі») → ✅ **Przy okazji / Nawiasem mówiąc, gdzie mieszkasz?** — **między innymi** = «зокрема».
- ⚠️ **między domem i szkołą** (трапляється, але менш ретельно) → ✅ **między domem a szkołą** — у парі «між X і Y» зразкова польська форма — з **a**.
- ❌ ~~Mówię polską~~ (калька з «говорю польською») → ✅ **Mówię po polsku** — «якою мовою» = **po** + форма на **-u** [[adv-form]]; **mówić językiem polskim** — можливо, але книжн., у побуті так не кажуть.
- ❌ ~~chronić od słońca~~ → ✅ **chronić przed słońcem** — захищати / тікати / попереджати = **przed** + О.`,
